from decimal import Decimal, localcontext, ROUND_HALF_EVEN
from functools import lru_cache, cmp_to_key
import sys
sys.setrecursionlimit(10000)
def pedestrian(s):
 v=list(map(int,s.split()));n=v[0];marks=v[1::2];lengths=v[2::2];intervals=[]
 for i,(m,length) in enumerate(zip(marks,lengths)):
  a,b=m-length,m+length
  if (i==0 or a>marks[i-1]) and (i==n-1 or b<marks[i+1]):intervals.append((b,a))
 last=None;answer=0
 for right,left in sorted(intervals):
  if last is None or left>last:answer+=1;last=right
 return str(answer)

sys.stdout.write(pedestrian(sys.stdin.read()) + "\n")

from decimal import Decimal, localcontext, ROUND_HALF_EVEN
from functools import lru_cache, cmp_to_key
import sys
