def bricks(s):
 v=list(map(int,s.split()));n,M=v[:2];dp=[-10**9]*(M+1);dp[0]=0
 for x in v[2:]:
  for j in range(M,x-1,-1):dp[j]=max(dp[j],dp[j-x]+1)
 return str(max(dp))

sys.stdout.write(bricks(sys.stdin.read()) + "\n")
